    public var skHex: String
    public var npub: String
    /**
     * Display name from the backup, may be empty.
     */
    public var name: String
    /**
     * peer npub -> display name map (JSON object string).
     */
    public var contactNamesJson: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Portable secret (store in Keychain).
         */skHex: String, npub: String, 
        /**
         * Display name from the backup, may be empty.
         */name: String, 
        /**
         * peer npub -> display name map (JSON object string).
         */contactNamesJson: String) {
        self.skHex = skHex
        self.npub = npub
        self.name = name
        self.contactNamesJson = contactNamesJson
    }
}



extension BackupIdentity: Equatable, Hashable {
    public static func ==(lhs: BackupIdentity, rhs: BackupIdentity) -> Bool {
        if lhs.skHex != rhs.skHex {
            return false
        }
        if lhs.npub != rhs.npub {
            return false
        }
        if lhs.name != rhs.name {
            return false
        }
        if lhs.contactNamesJson != rhs.contactNamesJson {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(skHex)
        hasher.combine(npub)
        hasher.combine(name)
        hasher.combine(contactNamesJson)
    }
}


