/**
 * Errors surfaced to Swift.
 */
public enum MurmurError {

    
    
    case InvalidHex(msg: String
    )
    case InvalidNpub(msg: String
    )
    case Crypto(msg: String
    )
    case Backup(msg: String
    )
    case Serde(msg: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeMurmurError: FfiConverterRustBuffer {
    typealias SwiftType = MurmurError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> MurmurError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidHex(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 2: return .InvalidNpub(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Crypto(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Backup(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Serde(
            msg: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: MurmurError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidHex(msg):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .InvalidNpub(msg):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Crypto(msg):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Backup(msg):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Serde(msg):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(msg, into: &buf)
            
        }
    }
}


extension MurmurError: Equatable, Hashable {}

extension MurmurError: Foundation.LocalizedError {
    public var errorDescription: String? {
        String(reflecting: self)
    }
}
